<script setup lang="ts">import {Run} from '../types/domain';import {median,probability} from '../utils/format';defineProps<{run:Run}>()</script><template><div class="run-summary"><div v-for="(g,i) in run.result.groups" :key="g.cohort.id" :class="['group-summary','group-'+i]"><span>{{g.cohort.code}} / {{g.cohort.process}}</span><h3>{{g.cohort.name}}</h3><b>{{median(g.median)}}</b><small>中位耐久 · {{g.events}} 事件 / {{g.censored}} 删失</small></div><div class="test-summary"><span>LOG-RANK / 双侧</span><b>{{probability(run.result.logrank.p_value)}}</b><small>{{run.result.logrank.estimable?'p 值 · 非因果结论':'无可比较事件或方差为零'}}</small></div></div></template>
